## D) OBSERVED PROPORTIONS PER COURSE (YES/NO THESIS)

# Recode completed_BIOE_195 to a clean Yes/No label.
sf <- student_flags %>%
  dplyr::mutate(
    CodedID = as.character(CodedID),
    Thesis  = ifelse(as.integer(as.character(completed_BIOE_195)) == 1, "Yes", "No")
  )

# For each field course, count thesis Yes/No among students who ever took that course.
overall_counts <- purrr::map_dfr(course_cols, function(col) {
  takers <- sf %>% dplyr::filter(.data[[col]] %in% c(1, "1", TRUE, "Yes"))
  tibble::tibble(Course = gsub("_", " ", sub("^completed_", "", col))) %>%
    dplyr::bind_cols(
      takers %>%
        dplyr::count(Thesis, name = "n") %>%
        tidyr::complete(Thesis = c("Yes", "No"), fill = list(n = 0))
    )
})

# Add a “No field course” reference group: students who never took any core field course.
no_fc_counts <- sf %>%
  dplyr::mutate(
    any_fc = rowSums(across(all_of(course_cols), ~ as.integer(. %in% c(1, "1", TRUE, "Yes"))), na.rm = TRUE)
  ) %>%
  dplyr::filter(any_fc == 0L) %>%
  dplyr::count(Thesis, name = "n") %>%
  tidyr::complete(Thesis = c("Yes", "No"), fill = list(n = 0)) %>%
  dplyr::mutate(Course = "No field course", .before = 1)

overall_counts <- dplyr::bind_rows(overall_counts, no_fc_counts)

# Keep only significant courses (from the model) plus the “No field course” baseline.
keep_courses <- c("No field course", results_sig$Course)
overall_counts_sig <- overall_counts %>%
  dplyr::filter(Course %in% keep_courses)

# Within each course, compute the proportion of Yes/No.
overall_props_sig <- overall_counts_sig %>%
  dplyr::group_by(Course) %>%
  dplyr::mutate(prop = n / sum(n)) %>%
  dplyr::ungroup()

# Total n per course for labels.
totals_sig <- overall_counts_sig %>%
  dplyr::group_by(Course) %>%
  dplyr::summarise(total = sum(n), .groups = "drop")

# Order courses by observed thesis-completion proportion (Yes) in descending order.
order_levels_sig <- overall_props_sig %>%
  dplyr::filter(Thesis == "Yes") %>%
  dplyr::arrange(dplyr::desc(prop)) %>%
  dplyr::pull(Course)

## E) PREDICTED PROBABILITY LABELS FOR SIGNIFICANT COURSES

# Prepare model-based p0–p1 ranges to overlay above bars for significant courses.
overlay_probs_sig <- results_sig %>%
  dplyr::filter(Course %in% order_levels_sig) %>%
  dplyr::mutate(
    Course      = factor(Course, levels = order_levels_sig),
    p0          = pmin(pmax(p0, 0), 1),
    p1          = pmin(pmax(p1, 0), 1),
    label_range = paste0(
      scales::percent(p0, accuracy = 0.1), "–",
      scales::percent(p1, accuracy = 0.1)
    )
  )

## F) COURSE LABELS FOR PLOTTING
# Map course codes to shorter display labels for the figure.
course_names <- tibble::tribble(
  ~Course,     ~CourseLabel,
  "BIOE 82",   "Intro Field Research",
  "BIOE 128L", "Large Marine Vert.",
  "BIOE 141L", "Behavioral Eco.",
  "BIOE 155L", "Freshwater Eco. Lab",
  "BIOE 151A", "Eco. & Conservation",
  "BIOE 145L", "Methods in Plant Eco."
)

## Helper function: merge course codes with readable labels.
# If a course appears in course_names, use its CourseLabel.
# If not (e.g., “No field course”), retain the original Course name.
add_course_labels <- function(df) {
  df %>%
    dplyr::mutate(Course = as.character(Course)) %>%         # ensure Course is character for joining
    dplyr::left_join(course_names, by = "Course") %>%        # add readable labels where available
    dplyr::mutate(
      CourseLabel = dplyr::coalesce(
        CourseLabel,                                         # use label if present
        dplyr::if_else(Course == "No field course",          # otherwise preserve “No field course”
                       "No field course",
                       Course)                               # fallback: use original course code
      )
    )
}

# Apply label mapping to each data frame used in plotting
overall_props_sig_lab <- add_course_labels(overall_props_sig)
totals_sig_lab        <- add_course_labels(totals_sig)
overlay_probs_sig_lab <- add_course_labels(overlay_probs_sig)

# Ordering vector translated into labeled factor levels
order_levels_sig_lab <- tibble::tibble(Course = as.character(order_levels_sig)) %>%
  dplyr::left_join(course_names, by = "Course") %>%
  dplyr::mutate(
    CourseLabel = dplyr::coalesce(
      CourseLabel,
      dplyr::if_else(Course == "No field course", "No field course", Course)
    )
  ) %>%
  dplyr::pull(CourseLabel)

## G) PLOT: FIELD COURSES VS. THESIS COMPLETION
