# Helper: lighten a hex color for ribbons.
.lighten <- function(col, f = 0.55) {
  m  <- grDevices::col2rgb(col)
  m2 <- m * (1 - f) + 255 * f
  grDevices::rgb(m2[1,], m2[2,], m2[3,], maxColorValue = 255)
}
ribbon_cols <- vapply(line_cols, .lighten, character(1))

# Helper: extract p-values from robust_ct() results.
.table_from_res <- function(res) {
  ct <- res$coeftest
  tibble::tibble(
    term = rownames(ct),
    p    = ct[, "Pr(>|z|)"]
  )
}

# Helper: build a prediction grid over the observed range of a focal term.
build_curve_data <- function(model, term, label, n = 200) {
  mf   <- model.frame(model)
  xvec <- mf[[term]]
  rng  <- range(xvec[is.finite(xvec)], na.rm = TRUE)
  if (!all(is.finite(rng))) return(NULL)
  
  # Vary the focal term over its observed range
  newdat <- tibble::tibble(!!term := seq(rng[1], rng[2], length.out = n))
  
  # Hold other covariates at their medians (numeric) or first level (factor)
  other_terms <- setdiff(attr(terms(model), "term.labels"), term)
  for (nm in other_terms) {
    if (!nm %in% names(mf)) next
    v <- mf[[nm]]
    if (is.numeric(v) || is.integer(v)) {
      newdat[[nm]] <- median(v, na.rm = TRUE)
    } else {
      newdat[[nm]] <- factor(levels(v)[1], levels = levels(v))
    }
  }
  
  # Predict on the link scale with standard errors
  pr <- predict(model, newdata = newdat, type = "link", se.fit = TRUE)
  eta <- as.numeric(pr$fit)
  se  <- as.numeric(pr$se.fit)
  
  tibble::tibble(
    panel = label,
    x     = newdat[[term]],
    prob  = plogis(eta),
    lo    = plogis(eta - 1.96 * se),
    hi    = plogis(eta + 1.96 * se)
  )
}

# Collect significant terms (per course).
# - BIOE 141L uses standard summary()
# - BIOE 82, 128L, 151A, 155L use robust_ct() p-values.
sig_list <- dplyr::bind_rows(
  {
    # BIOE 141L via standard summary
    sm <- summary(glm_BIOE_141L)$coefficients
    tb <- tibble::tibble(term = rownames(sm), p = sm[, ncol(sm)])
    cand <- names(candidates[["BIOE 141L"]])
    tb %>%
      dplyr::filter(term %in% cand, is.finite(p), p < alpha) %>%
      dplyr::mutate(
        panel  = unname(candidates[["BIOE 141L"]][term]),
        course = "BIOE 141L"
      )
  },
  {
    # BIOE 82 via robust_ct
    tb <- .table_from_res(res_82)
    cand <- names(candidates[["BIOE 82"]])
    tb %>%
      dplyr::filter(term %in% cand, is.finite(p), p < alpha) %>%
      dplyr::mutate(
        panel  = unname(candidates[["BIOE 82"]][term]),
        course = "BIOE 82"
      )
  },
  {
    # BIOE 128L via robust_ct
    tb <- .table_from_res(res_128L)
    cand <- names(candidates[["BIOE 128L"]])
    tb %>%
      dplyr::filter(term %in% cand, is.finite(p), p < alpha) %>%
      dplyr::mutate(
        panel  = unname(candidates[["BIOE 128L"]][term]),
        course = "BIOE 128L"
      )
  },
  {
    # BIOE 151A via robust_ct
    tb <- .table_from_res(res_151A)
    cand <- names(candidates[["BIOE 151A"]])
    tb %>%
      dplyr::filter(term %in% cand, is.finite(p), p < alpha) %>%
      dplyr::mutate(
        panel  = unname(candidates[["BIOE 151A"]][term]),
        course = "BIOE 151A"
      )
  },
  {
    # BIOE 155L via robust_ct
    tb <- .table_from_res(res_155L)
    cand <- names(candidates[["BIOE 155L"]])
    tb %>%
      dplyr::filter(term %in% cand, is.finite(p), p < alpha) %>%
      dplyr::mutate(
        panel  = unname(candidates[["BIOE 155L"]][term]),
        course = "BIOE 155L"
      )
  }
)

# Build predicted curves for all significant terms.
curves_sig <- sig_list %>%
  dplyr::select(course, term, panel) %>%
  purrr::pmap_dfr(function(course, term, panel) {
    if (course == "BIOE 82") {
      build_curve_data(glm_BIOE_82,   term, panel)
    } else if (course == "BIOE 128L") {
      build_curve_data(glm_BIOE_128L, term, panel)
    } else if (course == "BIOE 141L") {
      build_curve_data(glm_BIOE_141L, term, panel)
    } else if (course == "BIOE 151A") {
      build_curve_data(glm_BIOE_151A, term, panel)
    } else if (course == "BIOE 155L") {
      build_curve_data(glm_BIOE_155L, term, panel)
    } else {
      tibble::tibble()
    }
  })

# Fix facet order for panels and match colors to panel labels.
panel_order <- c(
  "Intro. to Field Research — Timing",
  "Large Marine Vert. — Applicant GPA",
  "Large Marine Vert. — Timing",
  "Behavioral Eco. — Timing",
  "Eco & Conservation — Timing",
  "Eco & Conservation — Applicant GPA",
  "Freshwater Eco. — Timing"
)

curves_sig$panel <- factor(curves_sig$panel, levels = panel_order)

line_cols_used   <- line_cols[names(line_cols) %in% levels(curves_sig$panel)]
ribbon_cols_used <- vapply(line_cols_used, .lighten, character(1))

# Final figure: per-course predicted probability curves with 95% CIs,
# one panel per significant effect (timing or GPA).
p_sig_curves <- ggplot(curves_sig, aes(x = x, y = prob, color = panel, fill = panel)) +
  geom_ribbon(aes(ymin = lo, ymax = hi), alpha = 0.35, color = NA) +
  geom_line(linewidth = 1.2) +
  facet_wrap(~ panel, ncol = 1, scales = "free_x") +
  scale_color_manual(values = line_cols_used, guide = "none") +
  scale_fill_manual(values = ribbon_cols_used, guide = "none") +
  scale_y_continuous(labels = scales::percent_format(accuracy = 1), limits = c(0, 1)) +
  labs(x = NULL, y = "Predicted Probability of Thesis Completion") +
  theme(
    panel.grid.minor = element_blank(),
    strip.text       = element_text(face = "bold", hjust = 0, size = 13),
    axis.title.x     = element_text(margin = margin(t = 6), size = 20),
    axis.title.y     = element_text(margin = margin(r = 6), size = 20),
    axis.text        = element_text(size = 15),
    panel.spacing    = unit(1.5, "lines")
  )

print(p_sig_curves)

ggsave(
  filename = "./drafts/figures/prob_curves_per_course.png",
