## =========================
## SUPP TABLE 5: POWER ANALYSIS FROM MODEL 1
## =========================

library(pwr)

demo_power_table <- agg_all %>%
  group_by(Demographic) %>%
  summarise(
    factor = first(Demographic),
    N = sum(Total, na.rm = TRUE),
    k_levels = n_distinct(Value),
    df = k_levels - 1,
    thesis_yes = sum(ThesisYes, na.rm = TRUE),
    thesis_no = sum(ThesisNo, na.rm = TRUE),
    thesis_rate = thesis_yes / N,
    observed_cramers_v = sqrt(
      suppressWarnings(
        prop.test(x = ThesisYes, n = Total)$statistic
      ) / N
    ),
    p_value = suppressWarnings(
      prop.test(x = ThesisYes, n = Total)$p.value
    ),
    .groups = "drop"
  ) %>%
  rowwise() %>%
  mutate(
    power_observed_effect = ifelse(
      is.finite(observed_cramers_v) & observed_cramers_v > 0 & df > 0,
      pwr.chisq.test(
        w = observed_cramers_v,
        N = N,
        df = df,
        sig.level = 0.05
      )$power,
      NA_real_
    ),
    
    min_detectable_cramers_v_80_power = ifelse(
      df > 0,
      pwr.chisq.test(
        N = N,
        df = df,
        sig.level = 0.05,
        power = 0.80
      )$w,
      NA_real_
    )
  ) %>%
  ungroup() %>%
  mutate(
    p_adj = p.adjust(p_value, method = "BH")
  ); demo_power_table

eth_power_check <- agg_all %>%
  filter(Demographic == "Race/Ethnicity") %>%
  transmute(
    Race_Ethnicity = Value,
    Total = Total,
    ThesisYes = ThesisYes,
    ThesisNo = ThesisNo,
    ThesisRate = ThesisYes / Total
  ) %>%
  arrange(Total); eth_power_check

supp_power_table <- demo_power_table %>%
  select(
    factor,
    k_levels,
    thesis_rate,
    observed_cramers_v,
    p_value,
    p_adj,
    power_observed_effect,
    min_detectable_cramers_v_80_power
  ) %>%
  rename(
    Demographic = factor,
    Levels = k_levels,
    Thesis_Rate = thesis_rate,
    Observed_Cramers_V = observed_cramers_v,
    P_Value = p_value,
    FDR_Adjusted_P = p_adj,
    Observed_Power = power_observed_effect,
    Min_Detectable_V_80_Power = min_detectable_cramers_v_80_power
  )

supp_power_gt <- supp_power_table %>%
  gt() %>%
  tab_header(
    title = md("**Supplementary Table S4b**"),
    subtitle = "Power analysis for demographic predictors of senior thesis participation"
  ) %>%
  fmt_number(
    columns = c(
      Thesis_Rate,
      Observed_Cramers_V,
      Observed_Power,
      Min_Detectable_V_80_Power
    ),
    decimals = 3
  ) %>%
  fmt_scientific(
    columns = c(P_Value, FDR_Adjusted_P),
    decimals = 2
  ) %>%
  cols_label(
