## =========================
## SUPP FIGURE 3: PERMUTATION TEST FIGURE
## =========================

# Clean enrollment records
enrollments <- time_completed_summary %>%
  filter(SE.Student.Enrollment.Status.Code == "E") %>%
  transmute(
    CodedID = as.character(CodedID),
    term = suppressWarnings(as.integer(TA.Term.Code)),
    course = str_squish(as.character(SE.Subject.Catalog.Nbr)),
    instructor = str_squish(as.character(CI.Instructor.Name))
  ) %>%
  filter(!is.na(CodedID), CodedID != "", !is.na(term)) %>%
  distinct()

# First BIOE 195 term for each student
first_thesis_term <- enrollments %>%
  filter(course == "BIOE 195") %>%
  group_by(CodedID) %>%
  summarise(first_195_term = min(term), .groups = "drop")

# Advisor(s) recorded in that first BIOE 195 term
thesis_roster <- enrollments %>%
  inner_join(first_thesis_term, by = "CodedID") %>%
  filter(
    course == "BIOE 195",
    term == first_195_term,
    !is.na(instructor), instructor != ""
  ) %>%
  group_by(CodedID, first_195_term) %>%
  summarise(
    advisor_set = list(unique(instructor)),
    .groups = "drop"
  )

# All non-195 instructors from strictly earlier terms
prior_sets <- enrollments %>%
  inner_join(first_thesis_term, by = "CodedID") %>%
  filter(
    course != "BIOE 195",
    term < first_195_term,
    !is.na(instructor), instructor != ""
  ) %>%
  group_by(CodedID) %>%
  summarise(
    prior_set = list(unique(instructor)),
    .groups = "drop"
  )

# One row per student; retain students with no prior instructors
perm_students <- thesis_roster %>%
  left_join(prior_sets, by = "CodedID") %>%
  mutate(
    prior_set = lapply(
      prior_set,
      function(x) if (is.null(x)) character(0) else x
    )
  )

stopifnot(
  nrow(perm_students) > 0,
  !anyDuplicated(perm_students$CodedID)
)

# Match if at least one assigned advisor previously taught the student
match_students <- function(assigned_sets) {
  vapply(seq_len(nrow(perm_students)), function(i) {
    any(assigned_sets[[i]] %in% perm_students$prior_set[[i]])
  }, logical(1))
}

observed_matches <- match_students(perm_students$advisor_set)
obs_prop <- mean(observed_matches)

# Shuffle entire advisor sets among students
set.seed(42)
n_perm <- 10000L

perm_props <- replicate(n_perm, {
  shuffled_sets <- perm_students$advisor_set[
    sample.int(nrow(perm_students))
  ]
  mean(match_students(shuffled_sets))
})

# One-sided Monte Carlo permutation p-value
p_val <- (1 + sum(perm_props >= obs_prop)) / (n_perm + 1)

permutation_summary <- tibble::tibble(
  students = nrow(perm_students),
  students_matched = sum(observed_matches),
  observed_pct = round(100 * obs_prop, 1),
  null_mean_pct = round(100 * mean(perm_props), 1),
  p_value = p_val
)

print(permutation_summary)

# Permutation figure
p_perm <- ggplot(
  tibble::tibble(match_rate = perm_props),
  aes(x = match_rate)
) +
  geom_histogram(
    bins = 30, fill = "#488B9E", colour = "white"
  ) +
  geom_vline(
    xintercept = obs_prop,
    colour = "#C52D29", linetype = "dashed", linewidth = 1
  ) +
  scale_x_continuous(
    labels = scales::label_percent(accuracy = 1),
    limits = range(c(perm_props, obs_prop))
  ) +
  labs(
    x = "Student–advisor match rate",
    y = "Number of permutations",
    subtitle = sprintf(
      "Observed (dashed line): %.1f%% | Permutation mean: %.1f%%",
      100 * obs_prop, 100 * mean(perm_props)
    )
  ) +
  theme_classic(base_size = 15)

print(p_perm)

ggsave(
  "outputs/figures/permutation_student_advisor.png",
  plot = p_perm,
  width = 8, height = 6, dpi = 600, bg = "white"
)